code.cpp:
class Solution {
public:
    string strWithout3a3b(int a, int b) {
        string s;
        s.reserve(a + b);
        while (a > 0 || b > 0) {
            int n = s.size();
            bool writeA;
            if (n >= 2 && s[n - 1] == s[n - 2]) {
                writeA = (s[n - 1] == 'b');
            } else {
                writeA = (a >= b);
            }
            if (writeA) {
                s += 'a';
                a--;
            } else {
                s += 'b';
                b--;
            }
        }
        return s;
    }
};
